unsafe fn Mask_calcN1N3(
    mut length: c_int,
    mut runLength: *mut c_int,
) -> c_int {
    let mut demerit: c_int = 0;
    let len = length;
    let mut i: c_int = 0;

    while i < len {
        // SAFETY: `runLength` is assumed valid for reads of `length` contiguous `c_int`
        // elements by the original function contract, and `i < len == length` here.
        let cur = unsafe { *runLength.add(i as usize) };

        if cur >= 5 {
            demerit += N1 + (cur - 5);
        }

        if (i & 1) != 0 && i >= 3 && i < len - 2 && cur % 3 == 0 {
            let fact = cur / 3;

            // SAFETY: Guard `i >= 3 && i < len - 2` ensures accesses at
            // `i-2`, `i-1`, `i+1`, and `i+2` are within `[0, length)`.
            if unsafe {
                *runLength.add((i - 2) as usize) == fact
                    && *runLength.add((i - 1) as usize) == fact
                    && *runLength.add((i + 1) as usize) == fact
                    && *runLength.add((i + 2) as usize) == fact
            } {
                if i == 3
                    // SAFETY: This branch only evaluates when `i != 3`, and with `i >= 3`
                    // the index `i-3` is within bounds.
                    || unsafe { *runLength.add((i - 3) as usize) } >= 4 * fact
                    || i + 4 >= len
                    // SAFETY: This branch only evaluates when `i + 4 < len`; combined with
                    // `i < len - 2`, index `i+3` is within bounds.
                    || unsafe { *runLength.add((i + 3) as usize) } >= 4 * fact
                {
                    demerit += N3;
                }
            }
        }

        i += 1;
    }

    demerit
}

